"""libbufs messages in Python: the reader (Table) and builder (MessageBuilder) that code generated by `bufsc --py` is
written against. The format is described in libbufs/docs/design.md: little-endian, 8-aligned, references are forward
offsets from their own slot, scalars are stored XOR their schema default.

Reading is bounds-checked (struct.error, MalformedMessage, IndexError), so a malformed message cannot read outside
itself; a reader never copies the message, it keeps a memoryview of it. Pure Python, no dependencies.
"""

import struct as _struct

__all__ = [
    "HEADER_BYTES", "MalformedMessage", "Table", "MessageBuilder", "Struct", "root_table", "message_type", "message_size",
    "read_list", "read_bytes", "read_strings", "read_tables", "read_structs", "enum_value",
]

HEADER_BYTES = 8

_U8 = _struct.Struct("<B")
_U16 = _struct.Struct("<H")
_U32 = _struct.Struct("<I")
_U64 = _struct.Struct("<Q")
_I8 = _struct.Struct("<b")
_I16 = _struct.Struct("<h")
_I32 = _struct.Struct("<i")
_I64 = _struct.Struct("<q")
_F32 = _struct.Struct("<f")
_F64 = _struct.Struct("<d")


class MalformedMessage(ValueError):
    pass


def _align4(n):
    return (n + 3) & ~3


def _view(data):
    return data if isinstance(data, memoryview) else memoryview(data)


def message_type(data):
    """The type id in a message's header, or 0 when it is too short."""
    v = _view(data)
    return _U32.unpack_from(v, 4)[0] if len(v) >= HEADER_BYTES else 0


def message_size(data):
    """The size a message declares in its header (the bytes it occupies; a frame may hold more)."""
    v = _view(data)
    return _U32.unpack_from(v, 0)[0] if len(v) >= 4 else 0


def root_table(data, type_id, type_name="message"):
    """Checks the header of `data` and returns its root Table."""
    v = _view(data)
    if len(v) < HEADER_BYTES + 4:
        raise MalformedMessage(f"{type_name}: message is too short")
    size = _U32.unpack_from(v, 0)[0]
    if size < HEADER_BYTES + 4 or size > len(v) or size % 8:
        raise MalformedMessage(f"{type_name}: bad message size")
    actual = _U32.unpack_from(v, 4)[0]
    if actual != type_id:
        raise MalformedMessage(f"{type_name}: wrong message type 0x{actual:x}")
    return Table(v, HEADER_BYTES)


def enum_value(cls, value):
    """The enum member for `value`, or the plain integer when the writer knew a member this schema does not."""
    try:
        return cls(value)
    except ValueError:
        return value


class Struct:
    """Base of generated structs: equality and repr by field."""

    __slots__ = ()

    def __eq__(self, other):
        return type(self) is type(other) and all(getattr(self, k) == getattr(other, k) for k in self.__slots__)

    def __repr__(self):
        return f"{type(self).__name__}({', '.join(f'{k}={getattr(self, k)!r}' for k in self.__slots__)})"


class Table:
    """A table of a message, read in place."""

    __slots__ = ("buf", "at", "data_bytes", "ref_count")

    def __init__(self, buf, at):
        self.buf = buf
        self.at = at
        self.data_bytes, self.ref_count = _struct.unpack_from("<HH", buf, at)

    # A scalar is stored XOR its schema default. A field past the writer's data section reads as 0, which
    # XOR the default is the default.

    def _raw(self, st, offset):
        return st.unpack_from(self.buf, self.at + offset)[0] if offset + st.size <= self.data_bytes else 0

    def u8(self, offset, dflt=0):
        return self._raw(_U8, offset) ^ dflt

    def u16(self, offset, dflt=0):
        return self._raw(_U16, offset) ^ dflt

    def u32(self, offset, dflt=0):
        return self._raw(_U32, offset) ^ dflt

    def u64(self, offset, dflt=0):
        return self._raw(_U64, offset) ^ dflt

    def i8(self, offset, dflt=0):
        return self._raw(_I8, offset) ^ dflt

    def i16(self, offset, dflt=0):
        return self._raw(_I16, offset) ^ dflt

    def i32(self, offset, dflt=0):
        return self._raw(_I32, offset) ^ dflt

    def i64(self, offset, dflt=0):
        return self._raw(_I64, offset) ^ dflt

    def f32(self, offset, dflt_bits=0):
        """`dflt_bits`: the bit pattern of the default."""
        return _F32.unpack(_U32.pack(self._raw(_U32, offset) ^ dflt_bits))[0]

    def f64(self, offset, dflt_bits=0):
        return _F64.unpack(_U64.pack(self._raw(_U64, offset) ^ dflt_bits))[0]

    def bit(self, byte, bit, dflt=0):
        return (((self.u8(byte) >> bit) & 1) ^ dflt) == 1

    def struct_at(self, offset, size):
        """Absolute offset of an inline struct of `size` bytes at `offset`, or -1 when the writer did not have it."""
        return self.at + offset if offset + size <= self.data_bytes else -1

    def ref(self, index):
        """Absolute offset the object reference `index` points to, or -1 when it is null or absent."""
        if index >= self.ref_count:
            return -1
        slot = self.at + _align4(self.data_bytes) + 4 * index
        relative = _U32.unpack_from(self.buf, slot)[0]
        return -1 if relative == 0 else slot + relative

    def vector(self, index):
        """(start, count) of the vector in reference `index`, or None."""
        target = self.ref(index)
        return None if target < 0 else (target + 4, _U32.unpack_from(self.buf, target)[0])

    def string(self, index):
        target = self.ref(index)
        return "" if target < 0 else _decode_string(self.buf, target)

    def table(self, index):
        target = self.ref(index)
        return None if target < 0 else Table(self.buf, target)


def _decode_string(buf, target):
    length = _U32.unpack_from(buf, target)[0]
    if target + 4 + length > len(buf):
        raise MalformedMessage("string runs past the end of the message")
    return bytes(buf[target + 4:target + 4 + length]).decode("utf-8", "replace")


def _check_vector(buf, start, count, element_bytes):
    if start + count * element_bytes > len(buf):
        raise MalformedMessage("vector runs past the end of the message")


def read_list(table, index, fmt, element_bytes):
    """The elements of a vector of scalars or enums: `fmt` is the struct format character of one element."""
    v = table.vector(index)
    if v is None:
        return []
    start, count = v
    _check_vector(table.buf, start, count, element_bytes)
    return list(_struct.unpack_from(f"<{count}{fmt}", table.buf, start))


def read_bytes(table, index):
    """A vector of bytes, copied out."""
    v = table.vector(index)
    if v is None:
        return b""
    start, count = v
    _check_vector(table.buf, start, count, 1)
    return bytes(table.buf[start:start + count])


def read_strings(table, index):
    v = table.vector(index)
    if v is None:
        return []
    start, count = v
    _check_vector(table.buf, start, count, 4)
    out = []
    for i in range(count):
        slot = start + 4 * i
        relative = _U32.unpack_from(table.buf, slot)[0]
        out.append("" if relative == 0 else _decode_string(table.buf, slot + relative))
    return out


def read_tables(table, index):
    v = table.vector(index)
    if v is None:
        return []
    start, count = v
    _check_vector(table.buf, start, count, 4)
    out = []
    for i in range(count):
        slot = start + 4 * i
        out.append(Table(table.buf, slot + _U32.unpack_from(table.buf, slot)[0]))
    return out


def read_structs(table, index, size, read):
    v = table.vector(index)
    if v is None:
        return []
    start, count = v
    _check_vector(table.buf, start, count, size)
    return [read(table.buf, start + i * size) for i in range(count)]


class MessageBuilder:
    """Builds one message front to back with the allocation rules of include/bufs/builder.hpp: tables 8-aligned, vectors
    4-aligned (4 mod 8 when their elements are 8 bytes), forward references, padding zeroed."""

    def __init__(self, type_id):
        self.buf = bytearray(256)
        self.used = 0
        self.allocate(HEADER_BYTES, 8, 0)
        _U32.pack_into(self.buf, 4, type_id)

    def allocate(self, nbytes, align, phase):
        """`nbytes` at an offset that is `phase` mod `align` (4 or 8; phase 0 or 4)."""
        at = self.used
        while at % align != phase:
            at += 4
        end = _align4(at + nbytes)
        if end > len(self.buf):
            self.buf.extend(bytes(max(end, len(self.buf) * 2) - len(self.buf)))
        self.used = end
        return at

    def table(self, data_bytes, ref_count):
        """A table: its u16 data_bytes and ref_count header written, the rest zero."""
        at = self.allocate(_align4(data_bytes) + 4 * ref_count, 8, 0)
        _struct.pack_into("<HH", self.buf, at, data_bytes, ref_count)
        return at

    def vector(self, count, element_bytes, element_align):
        """A vector of `count` elements; 8-byte elements are 8-aligned."""
        at = self.allocate(4 + count * element_bytes, 8, 4) if element_align == 8 else self.allocate(4 + count * element_bytes, 4, 0)
        _U32.pack_into(self.buf, at, count)
        return at

    def string(self, text):
        """A string: u32 length, the UTF-8 bytes, a NUL."""
        encoded = text.encode("utf-8")
        at = self.allocate(4 + len(encoded) + 1, 4, 0)
        _U32.pack_into(self.buf, at, len(encoded))
        self.buf[at + 4:at + 4 + len(encoded)] = encoded
        return at

    def pack_list(self, fmt, at, values):
        """Writes the elements of a vector of scalars (`fmt`: struct format character) at `at`."""
        if fmt in "Bb" and isinstance(values, (bytes, bytearray, memoryview)):
            self.buf[at:at + len(values)] = values
        else:
            _struct.pack_into(f"<{len(values)}{fmt}", self.buf, at, *values)

    def set_ref(self, table, data_bytes, ref_index, target):
        """Points reference slot `ref_index` of `table` (data section `data_bytes`) at `target`."""
        slot = table + _align4(data_bytes) + 4 * ref_index
        _U32.pack_into(self.buf, slot, target - slot)

    def set_element_ref(self, vector, index, target):
        slot = vector + 4 + 4 * index
        _U32.pack_into(self.buf, slot, target - slot)

    def set_u8(self, at, value, dflt=0):
        _U8.pack_into(self.buf, at, (int(value) ^ dflt) & 0xFF)

    def set_u16(self, at, value, dflt=0):
        _U16.pack_into(self.buf, at, (int(value) ^ dflt) & 0xFFFF)

    def set_u32(self, at, value, dflt=0):
        _U32.pack_into(self.buf, at, (int(value) ^ dflt) & 0xFFFFFFFF)

    def set_u64(self, at, value, dflt=0):
        _U64.pack_into(self.buf, at, (int(value) ^ dflt) & 0xFFFFFFFFFFFFFFFF)

    def set_i8(self, at, value, dflt=0):
        _U8.pack_into(self.buf, at, (int(value) ^ dflt) & 0xFF)

    def set_i16(self, at, value, dflt=0):
        _U16.pack_into(self.buf, at, (int(value) ^ dflt) & 0xFFFF)

    def set_i32(self, at, value, dflt=0):
        _U32.pack_into(self.buf, at, (int(value) ^ dflt) & 0xFFFFFFFF)

    def set_i64(self, at, value, dflt=0):
        _U64.pack_into(self.buf, at, (int(value) ^ dflt) & 0xFFFFFFFFFFFFFFFF)

    def set_f32(self, at, value, dflt_bits=0):
        _U32.pack_into(self.buf, at, _U32.unpack(_F32.pack(value))[0] ^ dflt_bits)

    def set_f64(self, at, value, dflt_bits=0):
        _U64.pack_into(self.buf, at, _U64.unpack(_F64.pack(value))[0] ^ dflt_bits)

    def set_bit(self, byte_at, bit, value, dflt=0):
        stored = (1 if value else 0) ^ dflt
        self.buf[byte_at] = (self.buf[byte_at] & ~(1 << bit) & 0xFF) | (stored << bit)

    def finish(self):
        """Seals the message: pads to 8, writes the size, returns the bytes."""
        end = self.allocate(0, 8, 0)
        _U32.pack_into(self.buf, 0, end)
        return bytes(self.buf[:end])
